def norm_url(url):
    p = urllib.parse.urlparse(url.lower())
    q = urllib.parse.parse_qs(p.query)
    for k in list(q.keys()):
        if any(t in k for t in ['utm_','ref','fbclid','gclid','sessionid','mc_eid']):
            del q[k]
    qs = urllib.parse.urlencode(q, doseq=True)
    path = p.path.rstrip('/')
    return f"{p.netloc}{path}" + (f"?{qs}" if qs else "")

