jsonl_path = os.path.join(base, "data", "articles.jsonl")
with open(jsonl_path, "a", encoding="utf-8") as f:
    for a in articles:
        f.write(json.dumps(a, ensure_ascii=False) + "\n")

print(f"OK: {len(articles)}件を articles.jsonl に追記しました")
